function act(obs, mem) {
  if (!mem) mem = {};
  const N = d => { while (d > 180) d -= 360; while (d < -180) d += 360; return d; };
  const C = (v, a, b) => v < a ? a : (v > b ? b : v);
  if (mem.esc === undefined) mem.esc = 1;

  // --- Smooth rays ---
  const raw = obs.rays || [10, 10, 10, 10, 10];
  if (!mem.rays) mem.rays = raw.slice();
  const rays = [];
  for (let i = 0; i < 5; i++) {
    mem.rays[i] = 0.7 * mem.rays[i] + 0.3 * raw[i];
    rays[i] = mem.rays[i];
  }

  // --- Stuck detection ---
  const px = mem.px !== undefined ? mem.px : obs.x;
  const py = mem.py !== undefined ? mem.py : obs.y;
  const ph = mem.ph !== undefined ? mem.ph : obs.heading;
  const dpos = Math.hypot(obs.x - px, obs.y - py);
  const dhead = Math.abs(N(obs.heading - ph));
  mem.px = obs.x; mem.py = obs.y; mem.ph = obs.heading;
  mem.stuckT = (dpos < 0.002 && dhead < 0.5) ? (mem.stuckT || 0) + 0.05 : 0;
  mem.travel = (mem.travel || 0) + dpos;

  // --- Target ---
  const dx = obs.targetX - obs.x, dy = obs.targetY - obs.y;
  const dist = Math.hypot(dx, dy) || 0.001;
  const err = N(Math.atan2(dy, dx) * 180 / Math.PI - obs.heading);

  // Reset on new target
  if (obs.targetIndex !== mem.lastTI) {
    mem.lastTI = obs.targetIndex;
    mem.escCount = 0;
    mem.state = null;
    mem.travel = 0;
  }

  // --- Escape mode ---
  if (mem.state === 'escape') {
    mem.escapeT -= 0.05;
    if (mem.escapeT <= 0) { mem.state = null; mem.stuckT = 0; }
    return { left: C(-0.6 - mem.esc * 0.4, -1, 1), right: C(-0.6 + mem.esc * 0.4, -1, 1) };
  }

  // Trigger escape
  if (mem.stuckT > 0.35) {
    mem.escCount = (mem.escCount || 0) + 1;
    mem.state = 'escape';
    mem.escapeT = 0.6 + 0.2 * mem.escCount;
    if (mem.travel < 1.0 && mem.escCount > 1) {
      mem.esc = -mem.esc;
    } else {
      const LO = rays[3] + rays[4], RO = rays[0] + rays[1];
      mem.esc = (LO >= RO) ? 1 : -1;
    }
    if (mem.travel >= 1.0) mem.escCount = 1;
    mem.travel = 0;
    return { left: C(-0.6 - mem.esc * 0.4, -1, 1), right: C(-0.6 + mem.esc * 0.4, -1, 1) };
  }

  // --- Obstacle avoidance (potential field) ---
  const angles = [-60, -30, 0, 30, 60];
  let rep = 0;
  const reach = 3.5;
  for (let i = 0; i < 5; i++) {
    const r = rays[i];
    if (r < reach) {
      let w = 1 - r / reach; w *= w;
      if (angles[i] !== 0) {
        rep += w * (-angles[i] / 60);
      } else {
        const LO = rays[3] + rays[4], RO = rays[0] + rays[1];
        rep += w * 2.0 * (LO >= RO ? 1 : -1);
      }
    }
  }
  rep = C(rep, -1.5, 1.5);

  // --- Steering ---
  let turn = C(err * 0.025 + rep * 1.0, -1, 1);

  // --- Speed ---
  const minR = Math.min(rays[0], rays[1], rays[2], rays[3], rays[4]);
  let speed = 1.0;
  if (minR < 2.0) speed = 0.6;
  if (minR < 1.0) speed = 0.35;
  if (Math.abs(err) > 45) speed = Math.min(speed, 0.5);
  if (Math.abs(err) > 100) speed = Math.min(speed, 0.3);
  if (Math.abs(turn) > 0.5) speed = Math.min(speed, 0.5);
  if (dist < 1.5) speed = Math.min(speed, C(dist * 0.5, 0.15, 1));

  return { left: C(speed - turn, -1, 1), right: C(speed + turn, -1, 1) };
}

function act(obs, mem) {
  if (!mem) mem = {};
  const N = d => { while (d > 180) d -= 360; while (d < -180) d += 360; return d; };
  const C = (v, a, b) => v < a ? a : (v > b ? b : v);

  if (mem.i === undefined) {
    mem.i = 1;
    mem.px = obs.x; mem.py = obs.y; mem.ph = obs.heading;
    mem.pL = 0; mem.pR = 0;
    mem.sm = [10, 10, 10, 10, 10];
    mem.stuck = 0;
    mem.escT = 0;
    mem.escDir = 1;
  }

  // Smooth rays
  const raw = obs.rays || [10, 10, 10, 10, 10];
  for (let k = 0; k < 5; k++) mem.sm[k] = 0.6 * mem.sm[k] + 0.4 * Math.max(0.01, raw[k]);
  const r = mem.sm;

  // Track movement
  const mdx = obs.x - mem.px, mdy = obs.y - mem.py;
  const mv = Math.hypot(mdx, mdy);
  const tn = Math.abs(N(obs.heading - mem.ph));
  mem.px = obs.x; mem.py = obs.y; mem.ph = obs.heading;
  mem.stuck = (mv < 0.008 && tn < 0.5) ? mem.stuck + 0.05 : 0;

  // GPS heading (only when moving forward at reasonable pace)
  if (mv > 0.04 && mv < 0.5 && obs.speed > 0.05) {
    const gH = Math.atan2(mdy, mdx) * 180 / Math.PI;
    mem.gH = (mem.gH === undefined) ? gH : mem.gH + 0.3 * N(gH - mem.gH);
  }
  const heading = (mem.gH !== undefined && mv > 0.03) ? mem.gH : obs.heading;

  // Target
  const dx = obs.targetX - obs.x, dy = obs.targetY - obs.y;
  const dist = Math.hypot(dx, dy);
  const bearing = Math.atan2(dy, dx) * 180 / Math.PI;
  const err = N(bearing - heading);

  // New target reset
  if (obs.targetIndex !== mem.ti) {
    mem.ti = obs.targetIndex;
    mem.stuck = 0;
    mem.escT = 0;
    mem.gH = undefined;
  }

  // EMERGENCY: raw ray < 0.35 m
  const rMin = Math.min(raw[0], raw[1], raw[2], raw[3], raw[4]);
  if (rMin < 0.35 && mem.escT <= 0) {
    if (raw[2] < 0.35) {
      mem.pL = -0.15; mem.pR = -0.15;
      return { left: -0.15, right: -0.15 };
    }
    let eS = 0;
    for (let k = 0; k < 5; k++) {
      if (raw[k] < 0.35) eS += ([-60, -30, 0, 30, 60][k] > 0) ? -0.3 : 0.3;
    }
    const l = C(-eS, -1, 1), rc = C(eS, -1, 1);
    mem.pL = l; mem.pR = rc;
    return { left: l, right: rc };
  }

  // ESCAPE: reverse then turn
  if (mem.escT > 0) {
    mem.escT -= 0.05;
    if (mem.escT > 0.5) {
      mem.pL = -0.3; mem.pR = -0.3;
      return { left: -0.3, right: -0.3 };
    }
    const tv = 0.2 * mem.escDir;
    mem.pL = -tv; mem.pR = tv;
    return { left: -tv, right: tv };
  }

  // STUCK TRIGGER
  if (mem.stuck > 0.4) {
    mem.escT = 1.2;
    mem.escDir = (r[3] + r[4]) >= (r[0] + r[1]) ? 1 : -1;
    mem.stuck = 0;
    mem.pL = -0.3; mem.pR = -0.3;
    return { left: -0.3, right: -0.3 };
  }

  // === DRIVE ===
  let avoid = 0;
  const REACH = 3.5;
  const RA = [-60, -30, 0, 30, 60];
  for (let k = 0; k < 5; k++) {
    const d = r[k];
    if (d < REACH && d > 0) {
      const w = ((REACH - d) / REACH) ** 2;
      if (RA[k] < 0) avoid += w;
      else if (RA[k] > 0) avoid -= w;
      else avoid += w * 2.5 * ((r[3] + r[4]) >= (r[0] + r[1]) ? 1 : -1);
    }
  }
  avoid = C(avoid, -0.5, 0.5);

  const hs = C(err * 0.008, -0.2, 0.2);
  let steer = C(hs + avoid * 0.5, -0.2, 0.2);

  const mR = Math.min(r[0], r[1], r[2], r[3], r[4]);
  let spd = 0.65;
  if (mR < 3.0) spd = 0.45;
  if (mR < 1.5) spd = 0.25;
  if (mR < 0.8) spd = 0.1;
  if (Math.abs(err) > 60) spd = Math.min(spd, 0.3);
  if (Math.abs(err) > 100) spd = Math.min(spd, 0.15);
  if (Math.abs(err) > 160) spd = 0;
  if (dist < 2) spd = Math.min(spd, 0.05 + 0.12 * dist);

  if (Math.abs(err) > 160) steer = err > 0 ? 0.25 : -0.25;

  let L = C(spd - steer, -1, 1);
  let R = C(spd + steer, -1, 1);

  // Rate limit to prevent oscillation with motor lag
  const MD = 0.06;
  L = C(L, mem.pL - MD, mem.pL + MD);
  R = C(R, mem.pR - MD, mem.pR + MD);
  mem.pL = L; mem.pR = R;

  return { left: L, right: R };
}

function act(obs, mem) {
  if (!mem) mem = {};
  const N = d => { while (d > 180) d -= 360; while (d < -180) d += 360; return d; };
  const C = (v, a, b) => v < a ? a : (v > b ? b : v);

