  // SPEED
  var speed = 0.7;
  var mR = Math.min(r[0], r[1], r[2], r[3], r[4]);
  if (mR < 3.0) speed = 0.5;
  if (mR < 1.5) speed = 0.3;
  if (mR < 0.8) speed = 0.1;
