  L = mem.L + C(L - mem.L, -0.08, 0.08);
  R = mem.R + C(R - mem.R, -0.08, 0.08);
  mem.L = C(L, -1, 1);
  mem.R = C(R, -1, 1);

  return { left: mem.L, right: mem.R };
}

function act(obs, mem) {
  if (!mem) mem = {};
  var N = function(d) { while (d > 180) d -= 360; while (d < -180) d += 360; return d; };
  var C = function(v, a, b) { return v < a ? a : (v > b ? b : v); };
  var DG = Math.PI / 180, RD = 180 / Math.PI;

  if (!mem.ini) {
    mem.ini = 1;
    mem.x0 = obs.x;
    mem.y0 = obs.y;
    mem.l0 = 0;
    mem.r0 = 0;
    mem.hb = 0;
    mem.ax = 0;
    mem.ay = 0;
    mem.sk = 0;
    mem.et = 0;
    mem.ed = 1;
    mem.en = 0;
    mem.ti = obs.targetIndex;
    mem.sr = [10, 10, 10, 10, 10];
    mem.tc = 0;
  }
  mem.tc++;

  var gx = obs.x - mem.x0, gy = obs.y - mem.y0;
  mem.x0 = obs.x;
  mem.y0 = obs.y;

  mem.ax = mem.ax * 0.85 + gx;
  mem.ay = mem.ay * 0.85 + gy;
  var am = Math.hypot(mem.ax, mem.ay);

  if (am > 0.5 && obs.speed > 0.1) {
    var gh = Math.atan2(mem.ay, mem.ax) * RD;
    var hb = N(gh - obs.heading);
    if (Math.abs(hb) < 45) mem.hb = C(mem.hb * 0.97 + hb * 0.03, -45, 45);
  }
  var hd = obs.heading + mem.hb;

  if (am < 0.05 && mem.tc > 20) mem.sk += 0.05;
  else mem.sk = 0;

  var rw = obs.rays || [10, 10, 10, 10, 10];
  for (var i = 0; i < 5; i++) mem.sr[i] = 0.5 * mem.sr[i] + 0.5 * rw[i];
  var sr = mem.sr;

  var tx = obs.targetX - obs.x, ty = obs.targetY - obs.y;
  var td = Math.hypot(tx, ty) || 0.01;
  var ta = Math.atan2(ty, tx) * RD;

  if (obs.targetIndex !== mem.ti) {
    mem.ti = obs.targetIndex;
    mem.sk = 0; mem.et = 0; mem.en = 0;
  }

  if (mem.et > 0) {
    mem.et -= 0.05;
    var el, er;
    if (mem.et > 0.3) { el = er = -0.2; }
    else { el = -0.2 * mem.ed; er = 0.2 * mem.ed; }
    mem.l0 = el; mem.r0 = er;
    return { left: el, right: er };
  }

  if (mem.sk > 0.5) {
    mem.en++;
    mem.et = 0.5 + 0.15 * Math.min(mem.en, 4);
    mem.ed = (sr[3] + sr[4] >= sr[0] + sr[1]) ? 1 : -1;
    if (mem.en % 3 === 0) mem.ed = -mem.ed;
    mem.sk = 0;
    mem.l0 = mem.r0 = -0.2;
    return { left: -0.2, right: -0.2 };
  }

  if (rw[2] < 1.0) {
    var w = (rw[3] + rw[4] >= rw[0] + rw[1]) ? 1 : -1;
    mem.l0 = -0.15 * w; mem.r0 = 0.2 * w;
    return { left: mem.l0, right: mem.r0 };
  }
  if (rw[1] < 0.5 && rw[3] >= 0.7) {
    mem.l0 = -0.1; mem.r0 = 0.15;
    return { left: -0.1, right: 0.15 };
  }
  if (rw[3] < 0.5 && rw[1] >= 0.7) {
    mem.l0 = 0.15; mem.r0 = -0.1;
    return { left: 0.15, right: -0.1 };
  }
  if (rw[0] < 0.3) {
    mem.l0 = -0.05; mem.r0 = 0.1;
    return { left: -0.05, right: 0.1 };
  }
  if (rw[4] < 0.3) {
    mem.l0 = 0.1; mem.r0 = -0.05;
    return { left: 0.1, right: -0.05 };
  }

  var px = tx / td * 2, py = ty / td * 2;
  var ra = [-60, -30, 0, 30, 60];
  for (var i = 0; i < 5; i++) {
    var d = Math.max(0.15, sr[i] - 0.35);
    if (d < 6) {
      var f = Math.min(3 / (d + 0.5), 8);
      var oa = (hd + ra[i]) * DG;
      px -= Math.cos(oa) * f;
      py -= Math.sin(oa) * f;
    }
  }

  if (sr[2] < 2.5) {
    var lt = (sr[3] + sr[4] - sr[0] - sr[1]) * 0.5;
    px += -Math.sin(hd * DG) * lt;
    py += Math.cos(hd * DG) * lt;
  }

  if (obs.x < 3) px += 2 / (obs.x + 0.5);
  if (obs.x > 37) px -= 2 / (40.5 - obs.x);
  if (obs.y < 3) py += 2 / (obs.y + 0.5);
  if (obs.y > 37) py -= 2 / (40.5 - obs.y);

  var pm = Math.hypot(px, py);
  var pa = pm < 0.01 ? ta : Math.atan2(py, px) * RD;
  var se = N(pa - hd);

  if (Math.abs(se) > 130 && sr[2] < 3) {
    se = (sr[3] + sr[4] >= sr[0] + sr[1]) ? 50 : -50;
  }

  var fm = Math.min(sr[1], sr[2], sr[3]);
  var sp;
  if (fm > 6) sp = 0.55;
  else if (fm > 4) sp = 0.4;
  else if (fm > 2.5) sp = 0.2;
  else if (fm > 1.5) sp = 0.08;
  else sp = 0;

  var as = Math.abs(se);
  if (as > 30) sp *= 0.7;
  if (as > 60) sp *= 0.4;
  if (as > 100) sp = 0;
  if (td < 2) sp = Math.min(sp, C(td * 0.1, 0, 0.15));

  var st = C(se * 0.008, -0.25, 0.25);

  var L = sp - st, R = sp + st;
  var av = (L + R) / 2;
  var df = C((R - L) / 2, -0.08, 0.08);
  L = av - df; R = av + df;

  L = mem.l0 + C(L - mem.l0, -0.06, 0.06);
  R = mem.r0 + C(R - mem.r0, -0.06, 0.06);
  mem.l0 = C(L, -1, 1);
  mem.r0 = C(R, -1, 1);
  return { left: mem.l0, right: mem.r0 };
}

function act(obs, mem) {
  obs = obs || {};
  mem = mem || {};

  function finite(v) {
    return typeof v === "number" && isFinite(v);
  }

  function clamp(v, lo, hi) {
    return v < lo ? lo : (v > hi ? hi : v);
  }

  function wrap(a) {
    while (a > 180) a -= 360;
    while (a < -180) a += 360;
    return a;
  }

  function pointValues(q) {
    if (Array.isArray(q)) {
      return [q[0], q[1]];
    }
    if (q && typeof q === "object") {
      return [q.x, q.y];
    }
    return [undefined, undefined];
  }

  if (!mem._roverInit) {
    mem._roverInit = true;
    mem._tick = 0;
    mem._mode = 0;              // 0: go to target, 1: follow obstacle, 2: recover
    mem._r = [10, 10, 10, 10, 10];
    mem._bias = 0;
    mem._trim = 0;
    mem._sx = undefined;
    mem._sy = undefined;
    mem._rawH = undefined;
    mem._blockX = undefined;
    mem._blockY = undefined;
    mem._blockH = 0;
    mem._lastTurn = 0;
    mem._targetKey = undefined;
    mem._avoidDir = 0;
    mem._lastAvoidDir = 0;
    mem._lastAvoidTick = -100000;
    mem._avoidTicks = 0;
    mem._clearTicks = 0;
    mem._switched = false;
    mem._hitDist = Infinity;
    mem._bestDist = Infinity;
    mem._recoverDir = 1;
    mem._recoverTicks = 0;
    mem._progDist = Infinity;
    mem._noProg = 0;
    mem._visits = Object.create(null);
    mem._centered = false;
    mem._arenaSet = false;
