    mem._goalIndex = index;
    mem._goalX = tx;
    mem._goalY = ty;
    mem._aimAbs = NaN;
    mem._avoidActive = false;
    mem._avoidClearSince = NaN;
    mem._avoidFlipCount = 0;
    mem._pivoting = false;
    mem._stuckTime = 0;
    mem._stallCheckT = t;
