    const plusCost = pathInfo(plusBeta).risk + wallRisk(plusBeta);
    const minusCost = pathInfo(minusBeta).risk + wallRisk(minusBeta);

    if (plusCost + 0.30 < minusCost) return 1;
    if (minusCost + 0.30 < plusCost) return -1;

    const plusOpen = plusBeta >= 0 ? leftOpen : rightOpen;
    const minusOpen = minusBeta >= 0 ? leftOpen : rightOpen;
    if (plusOpen > minusOpen + 0.4) return 1;
    if (minusOpen > plusOpen + 0.4) return -1;

    if (Number.isFinite(mem._lastSide) && Math.abs(goalRel) < 0.25) {
      return mem._lastSide;
    }
    return goalRel >= 0 ? 1 : -1;
  }

  function choosePhysicalSide() {
    if (leftOpen > rightOpen + 0.35) return 1;
    if (rightOpen > leftOpen + 0.35) return -1;
    if (Number.isFinite(mem._lastEscapeDir)) return -mem._lastEscapeDir;
    return goalRel >= 0 ? 1 : -1;
  }

  function send(drive, turn) {
