  if (!Number.isFinite(mem._stallCheckT)) {
    mem._stallCheckT = t;
    mem._stallCheckX = x;
    mem._stallCheckY = y;
    mem._stuckTime = 0;
  } else if (t - mem._stallCheckT >= 1.0) {
    const dt = t - mem._stallCheckT;
    const moved = Math.hypot(x - mem._stallCheckX, y - mem._stallCheckY);
    const stuck =
      moved < 0.18 &&
      targetDist > 2.2 &&
      Number.isFinite(mem._lastDrive) &&
      mem._lastDrive > 0.23 &&
      Math.abs(goalRel) < 2.55;

    if (stuck) {
      mem._stuckTime = (Number.isFinite(mem._stuckTime) ? mem._stuckTime : 0) + dt;
    } else {
      mem._stuckTime = Math.max(
        0,
        (Number.isFinite(mem._stuckTime) ? mem._stuckTime : 0) - 1.2 * dt
      );
    }

    mem._stallCheckT = t;
    mem._stallCheckX = x;
    mem._stallCheckY = y;

    const cooldown = Number.isFinite(mem._recoverCooldown) ? mem._recoverCooldown : -1;
    if (mem._stuckTime > 1.65 && t >= cooldown) {
