      mem._lastEscapeDir = mem._escapeDir;
      mem._escapeStart = t;
      mem._escapeUntil = t + 0.75;
      mem._recoverCooldown = t + 3.5;
      mem._stuckTime = 0;
      mem._avoidActive = false;
      mem._avoidClearSince = NaN;
      mem._lastSide = Number.isFinite(mem._avoidSide) ? -mem._avoidSide : -1;
      mem._aimAbs = NaN;
    }
  }

  if (Number.isFinite(mem._escapeUntil) && t < mem._escapeUntil) {
    const elapsed = t - (Number.isFinite(mem._escapeStart) ? mem._escapeStart : t);
    const dir = mem._escapeDir === -1 ? -1 : 1;
    let drive;
    let turn;

    if (elapsed < 0.25) {
      drive = -0.20;
      turn = dir * 0.24 - 0.06 * omega;
    } else if (elapsed < 0.55) {
      drive = 0.14;
      turn = dir * 0.34 - 0.06 * omega;
    } else {
      drive = 0.24;
      turn = dir * 0.24 - 0.06 * omega;
    }

    if (rawRays[2] < 0.45 && speedAbs > 0.45) drive = -0.20;
