      if (dir > 0 && leftOpen < 0.65 && rightOpen > leftOpen + 0.4) dir = -1;
      if (dir < 0 && rightOpen < 0.65 && leftOpen > rightOpen + 0.4) dir = 1;
      mem._pivotDir = dir;
      mem._pivoting = true;
      mem._avoidActive = false;
      mem._avoidClearSince = NaN;
      mem._aimAbs = NaN;
    }

    const dir = mem._pivotDir === -1 ? -1 : 1;
    const drive = speedAbs > 0.75 ? -0.10 : 0;
    const turn = clamp(dir * 0.30 - 0.08 * omega, -0.34, 0.34);
    return send(drive, turn);
  }
  mem._pivoting = false;

  const directRisk = pathInfo(clamp(goalRel, -1.9, 1.9)).risk;
  const centerBlocked =
    Math.abs(goalRel) < 0.35 &&
    rays[2] < 3.3;
