    const side = chooseAvoidSide();
    mem._avoidActive = true;
    mem._avoidSide = side;
    mem._lastSide = side;
    mem._avoidOffset = targetDist < 3 ? 0.55 : 0.76;
    mem._avoidAimAbs = wrap(targetAbs + side * mem._avoidOffset);
    mem._avoidStart = t;
    mem._avoidProgressT = t;
    mem._avoidBestDist = targetDist;
    mem._avoidFlipCount = 0;
    mem._avoidClearSince = NaN;
    mem._aimAbs = NaN;
  } else if (mem._avoidActive) {
    if (Math.abs(goalRel) > 2.25) {
      mem._avoidActive = false;
      mem._avoidClearSince = NaN;
      mem._aimAbs = NaN;
    } else {
      if (!Number.isFinite(mem._avoidBestDist) || targetDist < mem._avoidBestDist - 0.28) {
        mem._avoidBestDist = targetDist;
        mem._avoidProgressT = t;
      }

      if (directRisk < 1.2 && Math.abs(goalRel) < 1.65) {
        if (!Number.isFinite(mem._avoidClearSince)) mem._avoidClearSince = t;
        if (t - mem._avoidClearSince > 0.55) {
          mem._avoidActive = false;
          mem._avoidClearSince = NaN;
          mem._avoidFlipCount = 0;
          mem._aimAbs = NaN;
        }
      } else {
