    const info = pathInfo(beta);
    cost += info.risk;
    cost += wallRisk(beta);

    if (Number.isFinite(oldAimRel)) {
      const change = wrap(beta - oldAimRel);
      cost += 0.10 * change * change;
    }

    if (mem._avoidActive && (mem._avoidSide === 1 || mem._avoidSide === -1)) {
