    mem._aimAbs = rawAimAbs;
  } else {
    const alpha = urgent ? 0.55 : 0.30;
    mem._aimAbs = wrap(mem._aimAbs + alpha * wrap(rawAimAbs - mem._aimAbs));
  }

  const aimError = wrap(mem._aimAbs - heading);
  let drive = Math.min(0.68, 0.18 + 0.14 * Math.min(targetDist, 3.4));

  const aimInfo = pathInfo(aimError);
  const clearance = Math.min(bestInfo.clearance, aimInfo.clearance);
  const clearanceCap = 0.20 + 0.13 * clamp(clearance - 0.5, 0, 4.5);
  drive = Math.min(drive, clearanceCap);

  const absAimError = Math.abs(aimError);
  if (absAimError > 0.55) drive = Math.min(drive, 0.52);
  if (absAimError > 0.90) drive = Math.min(drive, 0.42);
  if (absAimError > 1.25) drive = Math.min(drive, 0.32);
  if (absAimError > 1.60) drive = Math.min(drive, 0.24);

  if (rays[2] < 2.8) {
    const frontCap = 0.15 + 0.17 * clamp(rays[2] - 0.45, 0, 2.35);
    drive = Math.min(drive, frontCap);
  }

  if (rawRays[2] < 0.50 && speedAbs > 0.65) {
    drive = Math.min(drive, -0.13);
  }

  const turn = clamp(0.58 * aimError - 0.09 * omega, -0.30, 0.30);
  return send(drive, turn);
