    ? obs.t
    : (Number.isFinite(mem._lastT) ? mem._lastT + 0.05 : 0);
  mem._lastT = t;

  const x = Number.isFinite(obs.x) ? obs.x : 0;
  const y = Number.isFinite(obs.y) ? obs.y : 0;
  const heading = wrap((Number.isFinite(obs.heading) ? obs.heading : 0) * DEG);
  const speed = Number.isFinite(obs.speed) ? obs.speed : 0;
