    ? obs.targetX
    : (Number.isFinite(obs.goalX) ? obs.goalX : x);
  const ty = Number.isFinite(obs.targetY)
    ? obs.targetY
    : (Number.isFinite(obs.goalY) ? obs.goalY : y);

