    mem._goalIndex = index;
    mem._goalX = tx;
    mem._goalY = ty;
    mem._aimAbs = NaN;
    mem._avoidActive = false;
    mem._avoidSide = 0;
    mem._avoidClearSince = NaN;
    mem._avoidFlipCount = 0;
    mem._pivoting = false;
    mem._stuckTime = 0;
    mem._stallCheckT = t;
    mem._stallCheckX = x;
    mem._stallCheckY = y;
    mem._lastDrive = 0;
    mem._escapeUntil = NaN;
