    const plusBeta = clamp(goalRel + 0.68, -1.68, 1.68);
    const minusBeta = clamp(goalRel - 0.68, -1.68, 1.68);

    const plusCost =
      pathInfo(plusBeta).risk +
      wallRisk(plusBeta) +
      1.25 * (1 - Math.cos(plusBeta - goalRel));
    const minusCost =
      pathInfo(minusBeta).risk +
      wallRisk(minusBeta) +
      1.25 * (1 - Math.cos(minusBeta - goalRel));

    if (plusCost + 0.22 < minusCost) return 1;
    if (minusCost + 0.22 < plusCost) return -1;

    const plusOpen = plusBeta >= 0 ? leftOpen : rightOpen;
    const minusOpen = minusBeta >= 0 ? leftOpen : rightOpen;
    if (plusOpen > minusOpen + 0.35) return 1;
    if (minusOpen > plusOpen + 0.35) return -1;

