    const right = drive + turn;
    const scale = Math.max(1, Math.abs(left), Math.abs(right));

    return {
      left: clamp(left / scale, -1, 1),
      right: clamp(right / scale, -1, 1)
    };
  }

  if (!Number.isFinite(mem._stallCheckT)) {
    mem._stallCheckT = t;
    mem._stallCheckX = x;
    mem._stallCheckY = y;
    mem._stuckTime = 0;
  } else if (t - mem._stallCheckT >= 1.0) {
    const dt = t - mem._stallCheckT;
    const moved = Math.hypot(x - mem._stallCheckX, y - mem._stallCheckY);
    const stuck =
      moved < 0.18 &&
      targetDist > 2.4 &&
      speedAbs < 0.42 &&
      Number.isFinite(mem._lastDrive) &&
      mem._lastDrive > 0.24 &&
      !mem._pivoting;

