  let compOffset = 0;
  if (mem.offsetSamples > 3) {
    compOffset = Math.atan2(mem.offsetSin, mem.offsetCos) * 180 / Math.PI;
  }
  const actualHeading = wrapDeg(obs.heading + compOffset);

  // Calibration: drive straight slowly to estimate compass offset
  if (!mem.calibrated) {
    if (obs.t >= mem.calibEnd) {
      mem.calibrated = true;
    } else {
      let left = 0.4, right = 0.4;
      if (obs.rays[2] < 0.8) { left = 0; right = 0; }
      return { left, right };
    }
  }

  updateMap(mem, obs, actualHeading);

  const targetX = obs.targetX;
  const targetY = obs.targetY;
  let [sx, sy] = worldToCell(obs.x, obs.y);
  let [tx, ty] = worldToCell(targetX, targetY);

  if (mem.map[idx(sx, sy)] === 2) mem.map[idx(sx, sy)] = 1;

  if (obs.t - mem.lastPlanT > 0.5 || mem.path.length === 0 || obs.targetIndex !== mem.lastTarget) {
    mem.lastPlanT = obs.t;
    mem.lastTarget = obs.targetIndex;
    let gtx = tx, gty = ty;
    if (isBlocked(mem.map, gtx, gty)) {
      const free = findFreeNear(mem.map, gtx, gty, 12);
      gtx = free[0]; gty = free[1];
    }
    mem.path = aStar(mem, sx, sy, gtx, gty);
    mem.pathIndex = 0;
  }

  let desiredX = targetX, desiredY = targetY;
  const distToTarget = Math.sqrt((targetX - obs.x) ** 2 + (targetY - obs.y) ** 2);
  if (distToTarget < 1.5) {
    desiredX = targetX;
    desiredY = targetY;
  } else if (mem.path.length > 0) {
    while (mem.pathIndex < mem.path.length) {
      const p = mem.path[mem.pathIndex];
      if (Math.sqrt((obs.x - p.x) ** 2 + (obs.y - p.y) ** 2) < 0.6) {
        mem.pathIndex++;
      } else {
        break;
      }
    }
    if (mem.pathIndex < mem.path.length) {
      desiredX = mem.path[mem.pathIndex].x;
      desiredY = mem.path[mem.pathIndex].y;
    }
  }

  const desiredHeading = Math.atan2(desiredY - obs.y, desiredX - obs.x) * 180 / Math.PI;
  let err = wrapDeg(desiredHeading - actualHeading);

  const front = obs.rays[2];
  const rightClear = Math.min(obs.rays[0], obs.rays[1]);
  const leftClear = Math.min(obs.rays[3], obs.rays[4]);
  let vTarget = 1.0;
  if (distToTarget < 2) vTarget = Math.min(vTarget, 0.3 + distToTarget * 0.3);
  if (front < 1.5) vTarget = Math.min(vTarget, Math.max(0.1, front * 0.5));
  if (front < 0.8) vTarget = Math.min(vTarget, 0.1);
  if (front < 0.5) vTarget = 0;

  if (front < 1.0) {
    if (leftClear > rightClear) err = Math.max(err, 40);
    else err = Math.min(err, -40);
    if (front < 0.6) {
      if (leftClear > rightClear) err = Math.max(err, 70);
      else err = Math.min(err, -70);
    }
  }
  if (obs.rays[1] < 0.6) err = Math.max(err, 30);
  if (obs.rays[3] < 0.6) err = Math.min(err, -30);
  if (obs.rays[0] < 0.5) err = Math.max(err, 20);
  if (obs.rays[4] < 0.5) err = Math.min(err, -20);

  if (vTarget > 0.2 && front > 0.8 && Math.abs(err) < 60 && obs.speed < 0.05 && moved < 0.01) {
    mem.stuckTime += dt;
  } else {
    mem.stuckTime = Math.max(0, mem.stuckTime - dt * 2);
  }
  if (mem.stuckTime > 1.0) {
    mem.recoverT = 1.2;
    mem.stuckTime = 0;
  }
  if (mem.recoverT > 0) {
    mem.recoverT -= dt;
    if (mem.recoverT > 0.6) {
      return { left: -0.5, right: -0.5 };
    } else {
      return { left: -0.6, right: 0.6 };
    }
