    const cur = pop();
    if (closed[cur]) continue;
    closed[cur] = 1;
    if (cur === goal) { best = cur; break; }

    const cx = cur % NX;
    const cy = (cur / NX) | 0;
    const hx = tx - cx, hy = ty - cy;
    const h = Math.sqrt(hx * hx + hy * hy);
    if (h < bestH) { bestH = h; best = cur; }

    for (let d = 0; d < 8; d++) {
      const nx = cx + DIRS[d][0];
      const ny = cy + DIRS[d][1];
      if (nx < 0 || nx >= NX || ny < 0 || ny >= NY) continue;
      if (isBlocked(mem, nx, ny)) continue;
      if (d >= 4) {
        if (isBlocked(mem, cx + DIRS[d][0], cy) || isBlocked(mem, cx, cy + DIRS[d][1])) continue;
      }
      const ni = ny * NX + nx;
      if (closed[ni]) continue;
      let step = DIRS[d][2];
      if (!mem.known[ni]) step *= 1.15;
      const tentative = g[cur] + step;
      if (tentative < g[ni]) {
        came[ni] = cur;
        g[ni] = tentative;
        const dhx = tx - nx, dhy = ty - ny;
        f[ni] = tentative + Math.sqrt(dhx * dhx + dhy * dhy);
        push(ni);
      }
    }
  }

  let c;
  if (came[goal] !== -1 || goal === start) c = goal;
  else if (best !== start) c = best;
  else return [];

  const path = [];
  while (c !== -1) {
    const gx = c % NX;
    const gy = (c / NX) | 0;
    path.push({ x: (gx + 0.5) * CELL, y: (gy + 0.5) * CELL });
    if (c === start) break;
    c = came[c];
  }
  path.reverse();
  return path;
}
function rebuildInfl(mem) {
  const infl = mem.infl;
  infl.fill(0);
  for (let x = 0; x < NX; x++) {
    for (let y = 0; y < NY; y++) {
      if (x < 2 || x >= NX - 2 || y < 2 || y >= NY - 2) {
        infl[y * NX + x] = 1;
      }
    }
  }
  for (let i = 0; i < N; i++) {
    if (mem.blocked[i]) {
      const cx = i % NX;
      const cy = (i / NX) | 0;
      for (let k = 0; k < OFF.length; k++) {
        const nx = cx + OFF[k][0];
        const ny = cy + OFF[k][1];
        if (nx >= 0 && nx < NX && ny >= 0 && ny < NY) {
          infl[ny * NX + nx] = 1;
        }
      }
    }
  }
}

function act(obs, mem) {
  if (!mem.init) {
    mem.init = true;
    mem.blocked = new Uint8Array(N);
    mem.hit = new Uint16Array(N);
    mem.free = new Uint16Array(N);
    mem.known = new Uint8Array(N);
    mem.infl = new Uint8Array(N);
    mem.g = new Float32Array(N);
    mem.f = new Float32Array(N);
    mem.came = new Int32Array(N);
    mem.closed = new Uint8Array(N);
    mem.open = [];
    mem.path = [];
    mem.pathIndex = 0;
    mem.lastPlanT = -10;
    mem.lastTargetIndex = -1;
    mem.vCmd = 0;
    mem.errInt = 0;
    mem.offSin = 0;
    mem.offCos = 1;
    mem.offSamples = 0;
    mem.lastOffT = obs.t;
    mem.lastOffX = obs.x;
    mem.lastOffY = obs.y;
    mem.lastOffHeading = obs.heading;
    mem.straightT = 0;
    mem.prevX = obs.x;
    mem.prevY = obs.y;
    mem.prevHeading = obs.heading;
    mem.headingRate = 0;
    mem.stuckT = 0;
    mem.recoverT = 0;
    mem.emgT = 0;
    mem.lastLeft = 0;
    mem.lastRight = 0;
    mem.lastT = obs.t;
    mem.calibrated = false;
    mem.calibEnd = obs.t + 1.0;
  }

  const dt = Math.min(0.1, Math.max(0.01, obs.t - mem.lastT));
  mem.lastT = obs.t;

  if (Math.abs(mem.lastLeft - mem.lastRight) < 0.3) mem.straightT += dt;
  else mem.straightT = 0;

  if (obs.t - mem.lastOffT > 1.0) {
    const dx = obs.x - mem.lastOffX;
    const dy = obs.y - mem.lastOffY;
    const d = Math.sqrt(dx * dx + dy * dy);
    const dh = Math.abs(wrapDeg(obs.heading - mem.lastOffHeading));
    if (d > 0.25 && dh < 25 && mem.straightT > 0.7) {
      const actual = Math.atan2(dy, dx) * 180 / Math.PI;
      const h0 = mem.lastOffHeading * Math.PI / 180;
      const h1 = obs.heading * Math.PI / 180;
      const avg = Math.atan2(Math.sin(h0) + Math.sin(h1), Math.cos(h0) + Math.cos(h1)) * 180 / Math.PI;
      const off = wrapDeg(actual - avg);
      if (Math.abs(off) < 85) {
        const rad = off * Math.PI / 180;
        const alpha = mem.offSamples < 2 ? 0.7 : 0.15;
        const oldSamples = mem.offSamples;
        mem.offSin = mem.offSin * (1 - alpha) + Math.sin(rad) * alpha;
        mem.offCos = mem.offCos * (1 - alpha) + Math.cos(rad) * alpha;
        mem.offSamples++;
        if (oldSamples === 0) {
          mem.blocked.fill(0);
          mem.hit.fill(0);
          mem.free.fill(0);
          mem.known.fill(0);
        }
      }
    }
    mem.lastOffX = obs.x;
    mem.lastOffY = obs.y;
    mem.lastOffHeading = obs.heading;
    mem.lastOffT = obs.t;
    mem.straightT = 0;
  }

  let compOffset = 0;
  if (mem.offSamples > 0) {
    compOffset = Math.atan2(mem.offSin, mem.offCos) * 180 / Math.PI;
  }
  const actualHeading = wrapDeg(obs.heading + compOffset);

  const dHead = wrapDeg(actualHeading - mem.prevHeading);
  mem.headingRate = mem.headingRate * 0.7 + (dHead / dt) * 0.3;
  mem.prevHeading = actualHeading;

  // Map update.
  const bx = clamp(Math.floor(obs.x / CELL), 0, NX - 1);
  const by = clamp(Math.floor(obs.y / CELL), 0, NY - 1);
  const bi = by * NX + bx;
  mem.blocked[bi] = 0;
  mem.hit[bi] = 0;
  mem.free[bi] = 0;
  mem.known[bi] = 1;

  for (let i = 0; i < 5; i++) {
    let r = obs.rays[i];
    const hasHit = r < 9.5;
    if (!hasHit) r = 10;
    if (r < 0) r = 0;
    const ang = (actualHeading + ANGLES[i]) * Math.PI / 180;
    const dx = Math.cos(ang), dy = Math.sin(ang);

    const steps = Math.floor(r / CELL);
    for (let s = 1; s <= steps; s++) {
      const d = s * CELL;
      if (d > r - 0.15) break;
      const mx = Math.floor((obs.x + dx * d) / CELL);
      const my = Math.floor((obs.y + dy * d) / CELL);
      if (mx >= 0 && mx < NX && my >= 0 && my < NY) {
        const ii = my * NX + mx;
        mem.known[ii] = 1;
        if (mem.free[ii] < 65000) mem.free[ii]++;
        if (mem.hit[ii] === 0 || mem.free[ii] > mem.hit[ii] + 2) {
          mem.blocked[ii] = 0;
        }
      }
    }

    if (hasHit && r > 0.15) {
      const hx = obs.x + dx * r;
      const hy = obs.y + dy * r;
      const hcx = Math.floor(hx / CELL);
      const hcy = Math.floor(hy / CELL);
      if (hcx >= 0 && hcx < NX && hcy >= 0 && hcy < NY) {
        const ii = hcy * NX + hcx;
        mem.known[ii] = 1;
        if (mem.hit[ii] < 65000) mem.hit[ii] += 2;
        mem.blocked[ii] = 1;
      }
    }
  }

  // Short straight calibration only if safe.
  if (!mem.calibrated) {
    if (obs.t >= mem.calibEnd || obs.rays[2] < 1.2) {
      mem.calibrated = true;
    } else {
      const v = 0.25;
      mem.lastLeft = v;
      mem.lastRight = v;
      return { left: v, right: v };
    }
  }

  const targetX = obs.targetX;
  const targetY = obs.targetY;
  const targetChanged = obs.targetIndex !== mem.lastTargetIndex;
  if (targetChanged) {
    mem.path = [];
    mem.pathIndex = 0;
    mem.errInt = 0;
    mem.stuckT = 0;
    mem.recoverT = 0;
  }

  const needPlan = targetChanged || mem.path.length === 0 || (obs.t - mem.lastPlanT > 1.2);
  if (needPlan) {
    rebuildInfl(mem);

    let sx = clamp(Math.floor(obs.x / CELL), 0, NX - 1);
    let sy = clamp(Math.floor(obs.y / CELL), 0, NY - 1);
    let tx = clamp(Math.floor(targetX / CELL), 0, NX - 1);
    let ty = clamp(Math.floor(targetY / CELL), 0, NY - 1);

    if (isBlocked(mem, sx, sy)) {
      const f = findFreeNear(mem, sx, sy, 12);
      sx = f[0]; sy = f[1];
    }
    if (isBlocked(mem, tx, ty)) {
      const f = findFreeNear(mem, tx, ty, 16);
      tx = f[0]; ty = f[1];
    }

    mem.path = plan(mem, sx, sy, tx, ty);
    mem.pathIndex = 0;
    mem.lastPlanT = obs.t;
    mem.lastTargetIndex = obs.targetIndex;
  }

  const distToTarget = Math.sqrt(
    (targetX - obs.x) * (targetX - obs.x) +
    (targetY - obs.y) * (targetY - obs.y)
  );

  let desiredX = targetX;
  let desiredY = targetY;

  if (distToTarget >= 0.9 && mem.path.length > 0) {
    while (mem.pathIndex < mem.path.length - 1) {
      const p = mem.path[mem.pathIndex];
      const d = Math.sqrt((p.x - obs.x) * (p.x - obs.x) + (p.y - obs.y) * (p.y - obs.y));
      if (d < 0.5) mem.pathIndex++;
      else break;
    }

    let found = false;
    for (let i = mem.pathIndex; i < mem.path.length; i++) {
      const p = mem.path[i];
      const d = Math.sqrt((p.x - obs.x) * (p.x - obs.x) + (p.y - obs.y) * (p.y - obs.y));
      if (d > 0.7) {
        desiredX = p.x;
        desiredY = p.y;
        found = true;
        break;
      }
    }
    if (!found) {
      desiredX = mem.path[mem.path.length - 1].x;
      desiredY = mem.path[mem.path.length - 1].y;
    }
  }

  const desiredHeading = Math.atan2(desiredY - obs.y, desiredX - obs.x) * 180 / Math.PI;
  let err = wrapDeg(desiredHeading - actualHeading);

  const front = obs.rays[2];
  const minF = Math.min(obs.rays[1], obs.rays[2], obs.rays[3]);
  const minS = Math.min(obs.rays[0], obs.rays[4]);
  const spd = Math.max(0, obs.speed);

  if (mem.emgT > 0) {
    mem.emgT -= dt;
    mem.lastLeft = -0.3;
    mem.lastRight = -0.3;
    return { left: -0.3, right: -0.3 };
  }

  if (front < 0.45 + spd * 0.6 || minF < 0.35 + spd * 0.4 || minS < 0.2) {
    mem.emgT = (front < 0.3 || minF < 0.25) ? 0.5 : 0.3;
    mem.lastLeft = -0.3;
    mem.lastRight = -0.3;
    return { left: -0.3, right: -0.3 };
  }

  const moved = Math.sqrt(
    (obs.x - mem.prevX) * (obs.x - mem.prevX) +
    (obs.y - mem.prevY) * (obs.y - mem.prevY)
  );
  mem.prevX = obs.x;
  mem.prevY = obs.y;

  if (mem.recoverT > 0) {
    mem.recoverT -= dt;
    let left, right;
    if (mem.recoverT > 0.5) {
      left = -0.3;
      right = -0.3;
    } else {
      const dir = err > 0 ? 1 : -1;
      left = -0.4 * dir;
      right = 0.4 * dir;
    }
    mem.lastLeft = left;
    mem.lastRight = right;
    return { left: clamp(left, -1, 1), right: clamp(right, -1, 1) };
  }

  if (Math.abs(mem.vCmd) > 0.15 && moved < 0.015) {
    mem.stuckT += dt;
  } else {
    mem.stuckT = Math.max(0, mem.stuckT - dt * 2);
  }
  if (mem.stuckT > 1.5) {
    mem.recoverT = 1.0;
    mem.stuckT = 0;
  }

  let vTarget = 0.85;
  const absErr = Math.abs(err);
  if (absErr > 100) vTarget = 0;
  else if (absErr > 60) vTarget = Math.min(vTarget, 0.15);
  else if (absErr > 35) vTarget = Math.min(vTarget, 0.35);
  else if (absErr > 18) vTarget = Math.min(vTarget, 0.6);

  if (distToTarget < 1.3) vTarget = Math.min(vTarget, 0.5);
  if (front < 0.9) vTarget = Math.min(vTarget, Math.max(0, (front - 0.45) * 1.2));
  if (minF < 0.7) vTarget = Math.min(vTarget, 0.25);
  if (minS < 0.35) vTarget = Math.min(vTarget, 0.35);
  if (minS < 0.25) vTarget = Math.min(vTarget, 0.15);

  if (vTarget < mem.vCmd) mem.vCmd = vTarget;
  else mem.vCmd = mem.vCmd * 0.8 + vTarget * 0.2;
  let v = Math.max(0, mem.vCmd);

  if (Math.abs(err) < 25 && v > 0.1) mem.errInt += err * dt;
  else mem.errInt *= 0.95;
  mem.errInt = clamp(mem.errInt, -30, 30);

  let turn = err * 0.006 + mem.errInt * 0.003 - mem.headingRate * 0.0015;
  turn = clamp(turn, -0.6, 0.6);

  if (v < 0.1 && Math.abs(err) > 15) {
    let left = -turn;
    let right = turn;
    if (Math.abs(left) < 0.15) left = left > 0 ? 0.15 : -0.15;
    if (Math.abs(right) < 0.15) right = right > 0 ? 0.15 : -0.15;
    left = clamp(left, -1, 1);
    right = clamp(right, -1, 1);
    mem.lastLeft = left;
    mem.lastRight = right;
    return { left, right };
  }

  let left = v - turn;
  let right = v + turn;

  if (Math.abs(left) > 0.02 && Math.abs(left) < 0.12) left = left > 0 ? 0.12 : -0.12;
  if (Math.abs(right) > 0.02 && Math.abs(right) < 0.12) right = right > 0 ? 0.12 : -0.12;

  left = clamp(left, -1, 1);
  right = clamp(right, -1, 1);

  mem.lastLeft = left;
  mem.lastRight = right;
  return { left, right };
}
